import fs from 'fs';
import path from 'path';
import { PRESET_COMP_ENTRIES } from '../presetComps/index';
import { COMP_LIBRARY } from '../compLibrary';

const PRESET_DIR = path.join(__dirname, '..', 'presetComps');

const filesOnDisk = fs
  .readdirSync(PRESET_DIR)
  .filter((f) => f.endsWith('.json'))
  .map((f) => f.replace(/\.json$/, ''))
  .sort((a, b) => a.localeCompare(b));

describe('presetComps/index.js barrel', () => {
  // index.js is generated by scripts/generatePresetCompsIndex.js, so a comp
  // dropped into the folder by hand (the app's "Preset comp file" save
  // downloads one) is invisible until the script runs again. It fails here
  // instead of silently missing from the Load Comp modal — which is exactly how
  // two Curious Coin comps went unnoticed: same roster as one already bundled,
  // so it read as the library refusing to show a duplicate.
  it('imports every JSON file in the folder', () => {
    const indexed = PRESET_COMP_ENTRIES.map((e) => e.key).sort((a, b) => a.localeCompare(b));
    const missing = filesOnDisk.filter((f) => !indexed.includes(f));

    expect(missing).toEqual([]);
    expect(indexed).toEqual(filesOnDisk);
  });

  it('gives every comp its own id, so none is dropped as a duplicate key', () => {
    const ids = COMP_LIBRARY.map((c) => c.id);
    expect(new Set(ids).size).toBe(ids.length);
  });

  // Comps that share a roster are normal and expected (the taxonomy reports
  // them as MISMO ROSTER): they differ in skills, trinkets or region. Nothing
  // in the library may collapse them into one row.
  it('keeps comps that share a roster as separate entries', () => {
    const rosterOf = (comp) => (comp.heroes || []).map((h) => (h && h.heroClass) || '-').join('|');
    const byRoster = new Map();
    COMP_LIBRARY.forEach((comp) => {
      const key = rosterOf(comp);
      byRoster.set(key, (byRoster.get(key) || 0) + 1);
    });
    const shared = [...byRoster.values()].filter((n) => n > 1);

    // If a dedupe ever crept in, the library would shrink to one row per roster.
    expect(shared.length).toBeGreaterThan(0);
    expect(COMP_LIBRARY.length).toBeGreaterThan(byRoster.size);
  });
});
